#include <algorithm>
#include <bit>
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <functional>
#include <immintrin.h>
#include <numeric>
#include <random>
#include <type_traits>
#include <vector>

namespace reinsirk::detail {
template<int Impl, class T, bool Minimize>
[[gnu::noinline]] void pop_pair(std::vector<T>& a, std::vector<T>& b) {
    const T last_a = a.back(), last_b = b.back();
    a.pop_back(); b.pop_back();
    T* const pa = a.data(); T* const pb = b.data();
    const std::size_t na = a.size(), nb = b.size();
    std::size_t ha = 0, hb = 0;
    const auto cmp = [](T x, T y) {
        if constexpr(Minimize) return x > y;
        else return x < y;
    };
    const auto descend = [&](T* data, std::size_t count, std::size_t& hole) {
        std::size_t child = hole * 2 + 1;
        if (child + 1 < count && cmp(data[child],data[child+1])) ++child;
        data[hole] = data[child]; hole = child;
    };
    if constexpr(Impl==0) {
        while(ha < na/2 && hb < nb/2) {
            descend(pa,na,ha); descend(pb,nb,hb);
        }
    } else {
        const auto full_a=na==0?0:(na-1)/2, full_b=nb==0?0:(nb-1)/2;
        while(ha<full_a && hb<full_b) {
            auto ca=ha*2+1, cb=hb*2+1;
            if constexpr(Impl==1) {
                ca+=static_cast<std::size_t>(cmp(pa[ca],pa[ca+1]));
                cb+=static_cast<std::size_t>(cmp(pb[cb],pb[cb+1]));
            } else {
                const __m128i va=_mm_loadu_si128(reinterpret_cast<const __m128i*>(pa+ca));
                const __m128i vb=_mm_loadu_si128(reinterpret_cast<const __m128i*>(pb+cb));
                __m128i left=_mm_unpacklo_epi64(va,vb),right=_mm_unpackhi_epi64(va,vb);
                if constexpr(std::is_unsigned_v<T>) {
                    const __m128i flip=_mm_set1_epi64x(std::bit_cast<std::int64_t>(std::uint64_t{1}<<63));
                    left=_mm_xor_si128(left,flip);right=_mm_xor_si128(right,flip);
                }
                const auto compared=Minimize?_mm_cmpgt_epi64(left,right):_mm_cmpgt_epi64(right,left);
                const auto mask=_mm_movemask_pd(_mm_castsi128_pd(compared));
                ca+=mask&1;cb+=(mask>>1)&1;
            }
            pa[ha]=pa[ca];ha=ca;pb[hb]=pb[cb];hb=cb;
        }
    }
    while(ha<na/2)descend(pa,na,ha);
    while(hb<nb/2)descend(pb,nb,hb);
    const auto restore=[&](T* data,std::size_t hole,T value) {
        while(hole!=0) {
            const auto parent=(hole-1)/2;
            if(!cmp(data[parent],value))break;
            data[hole]=data[parent];hole=parent;
        }
        data[hole]=value;
    };
    if(na)restore(pa,ha,last_a);
    if(nb)restore(pb,hb,last_b);
}
}
volatile std::uint64_t sink;
template<class T,bool Minimize>void run(std::size_t n,bool dup,int rep) {
    std::vector<T> ia(n),ib;
    if(dup)for(std::size_t i=0;i<n;++i)ia[i]=i%8;
    else {std::mt19937_64 random(77);for(auto& x:ia)x=static_cast<T>(random());}
    ib=ia;std::mt19937 ga(7),gb(9);std::shuffle(ia.begin(),ia.end(),ga);std::shuffle(ib.begin(),ib.end(),gb);
    const auto cmp=[](T x,T y) {if constexpr(Minimize)return x>y;else return x<y;};
    std::make_heap(ia.begin(),ia.end(),cmp);std::make_heap(ib.begin(),ib.end(),cmp);
    using Fn=void(*)(std::vector<T>&,std::vector<T>&);
    const Fn funcs[]{reinsirk::detail::pop_pair<0,T,Minimize>,reinsirk::detail::pop_pair<0,T,Minimize>,reinsirk::detail::pop_pair<1,T,Minimize>,reinsirk::detail::pop_pair<2,T,Minimize>};
    const char* names[]{"baseline","control","scalar_full","simd_full"};
    for(int order=0;order<4;++order) {
        int kind=(order+rep)%4;std::vector<T>a,b;std::uint64_t sum=0;
        const int repeats=n==32?10000:2;
        auto start=std::chrono::steady_clock::now();
        for(int i=0;i<repeats;++i) {
            a=ia;b=ib;
            while(!a.empty()) {sum+=static_cast<std::uint64_t>(a.front());funcs[kind](a,b);}
        }
        auto ns=std::chrono::duration<double,std::nano>(std::chrono::steady_clock::now()-start).count()/repeats;
        sink=sum;
        std::printf("%zu %d %d %s %.5f %llu\n",n,int(Minimize),int(dup),names[kind],ns,static_cast<unsigned long long>(sum));
    }
}
int main(int argc,char**argv) {
    int rep=argc>1?std::atoi(argv[1]):0;
    for(std::size_t n:{std::size_t{32},std::size_t{100000}}) for(bool dup:{false,true}) {
        run<std::int64_t,true>(n,dup,rep);run<std::int64_t,false>(n,dup,rep);
    }
}

